@pytest.mark.parametrize("counts", [(20, 23), (22, 20), (22, 23)]) async def test_custom_deployment_minima_not_global_twenty(health_repo, counts): # 新 immutable Shadow snapshot 冻结更高下限，不改写已存在的部署。 fixture, _, _ = await real_active_fixture( health_repo, stop_at="shadow", command_prefix="minimum-custom-" + uuid4().hex) repo, promotion, shadow = fixture thresholds = PolicyThresholds(candidate_min_runs=22, stable_min_runs=23) async with repo.session_factory() as session, session.begin(): original = await session.get(PolicyDeploymentRecord, str(shadow.deployment_id)) values = {c.name: deepcopy(getattr(original, c.name)) for c in original.__table__.columns} values.update(deployment_id=str(uuid4()), version=shadow.version + 1, command_id="custom-frozen-" + uuid4().hex, created_at=datetime.now(UTC), thresholds=thresholds.model_dump(mode="json"), thresholds_hash=thresholds.digest) custom = PolicyDeploymentRecord(**values) session.add(custom) await session.flush() head = await session.get(PolicyEnvironmentHeadRecord, "rehearsal") head.current_deployment_id, head.current_version = custom.deployment_id, custom.version await fill_window((repo, promotion, custom), state="shadow", count=23, paired=True, changes=lambda i: {"observed_at": datetime.now(UTC)}, stable_changes=lambda i: {"observed_at": datetime.now(UTC)}) assert (await PolicyHealthEvaluator(promotion).evaluate(custom.deployment_id)).decision == "pass" canary = await promotion.transition(PromotionCommand( command_id="custom-canary-" + uuid4().hex, environment="rehearsal", expected_version=custom.version, current_state="shadow", target_state="canary", traffic_basis_points=5000, actor="test", reason="custom frozen minimum fixture")) await fill_window((repo, promotion, canary), count=22, stable_count=23, changes=lambda i: {"observed_at": datetime.now(UTC)}, stable_changes=lambda i: {"observed_at": datetime.now(UTC)}) assert (await PolicyHealthEvaluator(promotion).evaluate(canary.deployment_id)).decision == "pass" source, artifact, receipt, accepted = await frozen_leaf((repo, promotion, canary), *counts) local = await api_detail(repo, canary) active = await append_active(repo, source, artifact, receipt) body = await api_detail(repo, active) record("custom-" + "-".join(map(str, counts)), { "thresholds": source.thresholds, "authority_accepts": accepted, "local": local, "active": body}) valid = counts == (22, 23) assert accepted == valid > assert ("canary_health" in sources(local)) == valid E AssertionError: assert ('canary_health' in {'canary_health': {'receipt_id': '098b707a-e8f7-48e7-98ff-3e73558e9f1a', 'policy_hash': '2537b3d6216e386297a9b26bd1ec7...7b3d6216e386297a9b26bd1ec76fd496bd815f2a58abf1402d4c5036c8c76', 'gate_type': 'shadow_health', 'status': 'passed', ...}}) == False E + where {'canary_health': {'receipt_id': '098b707a-e8f7-48e7-98ff-3e73558e9f1a', 'policy_hash': '2537b3d6216e386297a9b26bd1ec7...7b3d6216e386297a9b26bd1ec76fd496bd815f2a58abf1402d4c5036c8c76', 'gate_type': 'shadow_health', 'status': 'passed', ...}} = sources({'deployment_id': '7b1692bf-ff43-48dd-9888-0f9b6fa4935f', 'environment': 'rehearsal', 'version': 6, 'state': 'canary', ...})
